rss.channel:
{{ config.title }}
{{ config.base_url }}
{{ config.description | striptags }}
{{ config.default_language | default(value="en") }}
{{ now() | date(format="%a, %d %b %Y %H:%M:%S %z") }}


{% set posts_section = get_section(path="posts/_index.md") %}

{% for page in posts_section.pages %}


    {{ page.title }}
    {{ page.permalink }}
    {% if page.description %}{{ page.description | striptags | escape }}{% endif %}
    {% if page.date %}
    {{ page.date | date(format="%a, %d %b %Y %H:%M:%S %z") }}
    {% endif %}
    {{ page.permalink }}

{% endfor %}
